output_text:
[
  {
    "id": "must_take_cart_from_station",
    "text": "A shopper is obliged to take the available cart from the cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_station": "at(1,5)",
        "cart_stationed": "cartAt(1,5)"
      },
      "events": {
        "pickup_station_cart": {
          "pre": {
            "and": [
              "at_cart_station",
              "cart_stationed",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_station_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "A shopper is prohibited from picking up merchandise unless they currently have the shopping cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_hand": "hasCart",
        "no_cart_in_hand": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "no_cart_in_hand"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_for_goods": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_front_bay_after_shopping",
    "text": "After taking any required item, the shopper is obliged to return the cart to the front return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "front_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_item",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "A shopper is prohibited from exiting unless the cart has already been left in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "bad_exit_with_unreturned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bad_exit_with_unreturned_cart"
    }
  },
  {
    "id": "no_carts_in_narrow_cell_7_4",
    "text": "Cell (7,4) is a narrow pedestrian area, so carts are prohibited there but pedestrians without carts may pass through.",
    "abstraction": {
      "state_properties": {
        "narrow_pedestrian_cell": "at(7,4)",
        "cart_occupies_current_cell": "hasCart",
        "parked_cart_in_narrow_cell": "cartAt(7,4)"
      },
      "events": {
        "push_cart_into_narrow_cell": {
          "pre": "hasCart",
          "post": "at(7,4)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "narrow_pedestrian_cell",
              "cart_occupies_current_cell"
            ]
          },
          "parked_cart_in_narrow_cell",
          "push_cart_into_narrow_cell"
        ]
      }
    }
  },
  {
    "id": "one_way_exit_flow_after_cart_return",
    "text": "After the cart has been returned, the shopper must follow the one-way pedestrian exit flow and may not move north or west.",
    "abstraction": {
      "state_properties": {
        "post_cart_return_pedestrian": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "against_exit_flow_action": {
          "or": [
            "N",
            "W"
          ]
        }
      },
      "events": {
        "move_against_exit_flow_after_return": {
          "pre": {
            "and": [
              "post_cart_return_pedestrian",
              "against_exit_flow_action"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_against_exit_flow_after_return"
    }
  },
  {
    "id": "turn_back_after_egg_shelf_with_cart",
    "text": "After interacting at the egg shelf while pushing a cart, the shopper is obliged to turn back west rather than continue east with the cart.",
    "abstraction": {
      "state_properties": {
        "egg_shelf_position": "at(6,4)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "interact_at_egg_shelf_with_cart": {
          "pre": {
            "and": [
              "egg_shelf_position",
              "pushing_cart",
              "INTERACT"
            ]
          },
          "post": null
        },
        "west_from_egg_shelf_with_cart": {
          "pre": {
            "and": [
              "egg_shelf_position",
              "pushing_cart",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "interact_at_egg_shelf_with_cart",
      "discharge": "west_from_egg_shelf_with_cart"
    }
  }
]
